#include "../charge_compiler/json.hpp"
#include "sparse_runs_v2.hpp"
#include <gmpxx.h>
#include <iostream>
#include <time.h>
using I=long long;
static double now(){timespec t{};require(clock_gettime(CLOCK_BOOTTIME,&t)==0,"clock");return t.tv_sec+t.tv_nsec*1e-9;}
struct Bits{uint64_t significand;int exponent;bool negative;};
static Bits bits(long double value){char raw[10];std::memcpy(raw,&value,10);uint64_t s=sparse::load(raw);uint16_t e;std::memcpy(&e,raw+8,2);return {s,((e&0x7fff)?int(e&0x7fff)-16383:1-16383)-63,bool(e&0x8000)};}
int main(int argc,char**argv){try{
 require(argc==2,"usage CONFIG");auto cfg=Json::read(argv[1]);uint64_t nodes=cfg.at("node_count").integer();require(nodes>0&&nodes<=10000000,"bounded dyadic voltage count");double deadline=cfg.at("deadline_uptime").num();std::string path=cfg.at("matrix").str();int minimum=100000,maximum=-100000;uint64_t entries=0;
 {sparse::Reader input(path);sparse::Record r;while(input.next(r)){if(entries++%10000==0)require(now()<deadline,"dyadic first-pass deadline");require((r.key&UINT32_MAX)<nodes,"dyadic matrix voltage bounds");if(r.value==0)continue;auto b=bits(r.value);minimum=std::min(minimum,b.exponent);maximum=std::max(maximum,b.exponent);}}
 if(minimum==100000)minimum=maximum=0;require(maximum-minimum<=512,"bounded exact dyadic exponent span");uint64_t nets=1;std::vector<uint32_t> component(nodes,0);
 std::vector<mpz_class> residual(nodes),l1(nodes);uint64_t read=0,negative_edges=0;
 {sparse::Reader input(path);sparse::Record r;while(input.next(r)){if(read++%10000==0)require(now()<deadline,"dyadic exact accumulation deadline");uint32_t i=r.key>>32,j=r.key&UINT32_MAX;if(i!=j){negative_edges+=r.value<0;}if(r.value==0)continue;auto b=bits(r.value);mpz_class magnitude;mpz_import(magnitude.get_mpz_t(),1,-1,sizeof(b.significand),0,0,&b.significand);mpz_mul_2exp(magnitude.get_mpz_t(),magnitude.get_mpz_t(),b.exponent-minimum);mpz_class value=magnitude;if(b.negative)value=-value;residual[i]+=value;l1[i]+=magnitude;if(i!=j){residual[j]+=value;l1[j]+=magnitude;}}}require(read==entries,"both dyadic passes cover all entries");
 std::vector<mpz_class> energy(nets);
 std::ofstream exact(cfg.at("row_certificate").str());require(bool(exact),"exact row certificate open");
 mpz_class largest=0,best_numerator=0,best_denominator=1;uint64_t largest_row=0,best_row=0,negative_rows=0,positive_rows=0,zero_rows=0,outside=0;
 for(uint64_t i=0;i<nodes;i++){if(i%10000==0)require(now()<deadline,"dyadic row certificate deadline");require(component[i]<nets,"component ID bound");energy[component[i]]+=residual[i];Json row=Json::object();row["row"]=I(i);row["residual_integer"]=residual[i].get_str();row["L1_integer"]=l1[i].get_str();exact<<row.dump()<<'\n';int sign=mpz_sgn(residual[i].get_mpz_t());negative_rows+=sign<0;positive_rows+=sign>0;zero_rows+=sign==0;if(!sign)continue;mpz_class magnitude=abs(residual[i]);require(l1[i]>0,"nonzero residual has nonzero row norm");if(magnitude>largest){largest=magnitude;largest_row=i;}if(magnitude*best_denominator>best_numerator*l1[i]){best_numerator=magnitude;best_denominator=l1[i];best_row=i;}outside+=magnitude*1000000000000UL>l1[i];}
 exact.close();require(bool(exact),"exact row certificate close");uint64_t negative_energy=0,first_negative=UINT64_MAX;mpz_class first_energy=0;for(uint64_t i=0;i<nets;i++)if(energy[i]<0){negative_energy++;if(first_negative==UINT64_MAX){first_negative=i;first_energy=energy[i];}}
 mpq_class ratio(best_numerator,best_denominator);ratio.canonicalize();Json report=Json::object();report["upper_entries"]=I(entries);report["node_count"]=I(nodes);report["negative_offdiagonal_edges"]=I(negative_edges);report["common_binary_quantum_exponent"]=minimum;report["maximum_absolute_diagonal_perturbation_integer"]=largest.get_str();report["maximum_absolute_diagonal_perturbation_row"]=I(largest_row);report["maximum_scaled_diagonal_perturbation_numerator"]=ratio.get_num().get_str();report["maximum_scaled_diagonal_perturbation_denominator"]=ratio.get_den().get_str();report["maximum_scaled_diagonal_perturbation_approximate"]=ratio.get_d();report["maximum_scaled_diagonal_perturbation_row"]=I(best_row);report["negative_diagonal_perturbation_rows"]=I(negative_rows);report["positive_diagonal_perturbation_rows"]=I(positive_rows);report["zero_diagonal_perturbation_rows"]=I(zero_rows);report["rows_outside_existing_1e12_gauge_screen_exact"]=I(outside);report["within_existing_1e12_gauge_screen_exact"]=outside==0;report["negative_original_component_constant_energies"]=I(negative_energy);report["first_negative_component_constant_witness"]=Json();if(first_negative!=UINT64_MAX){Json witness=Json::object();witness["component_id"]=I(first_negative);witness["voltage_definition"]="one on this original conductor, zero elsewhere";witness["energy_integer"]=first_energy.get_str();witness["energy_binary_exponent"]=minimum;report["first_negative_component_constant_witness"]=witness;}report["exact_stored_coefficient_row_sums_certified"]=true;report["matrix_modified"]=false;report["physical_RC_qualified"]=false;report["release_qualified"]=false;std::ofstream out(cfg.at("report").str());out<<report.dump()<<'\n';require(bool(out),"dyadic certificate close");return 0;
 }catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
